  const stamp=r.id+'-'+(r.location?.updated_at||r.status);const oldImage=box.querySelector('.map')?.src;if(stamp!==mapStamp)mapStamp=stamp;const imageSrc=oldImage&&stamp===box.dataset.mapStamp?oldImage:'/api/carros/map?ride='+r.id+'&v='+encodeURIComponent(stamp);text+='<img class="map" src="'+esc(imageSrc)+'" alt="Mapa da corrida com origem, destino e localização autorizada">';box.dataset.mapStamp=stamp;
  text+='<div class="buttons">';if(mePassenger&&['accepted','arrived'].includes(r.status))text+='<button id="get-pin">Mostrar código de início</button>';if(meDriver&&r.status==='accepted')text+='<button class="primary" id="arrive">Cheguei ao local</button>';if(meDriver&&r.status==='arrived')text+='<button class="primary" id="start">Validar código e iniciar</button>';if(meDriver&&r.status==='in_progress')text+='<button class="primary" id="complete">Concluir corrida</button>';if(['searching','accepted','arrived'].includes(r.status)&&(mePassenger||meDriver)||operator&&r.status==='in_progress')text+='<button id="cancel">Cancelar com motivo</button>';if(operator&&['searching','accepted','arrived','no_driver'].includes(r.status))text+='<button id="reoffer">Reofertar</button>';if(operator)text+='<button id="incident">Registrar ocorrência</button>';if(mePassenger)text+='<button id="share">Compartilhar informações</button>';if(['completed','cancelled'].includes(r.status))text+='<button id="receipt">Imprimir resumo</button>';text+='</div>';
  if(pin&&mePassenger&&['accepted','arrived'].includes(r.status))text+='<p class="muted">Informe este código somente ao motorista no embarque.</p><div class="pin">'+esc(pin)+'</div>';
